import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import UploadPage from './pages/SimpleUploadPage';
import Dashboard from './pages/SimpleDashboard';
import ResearchInsights from './pages/SimpleResearchInsights';
import CAMPreview from './pages/SimpleCAMPreview';
import './App.css';

function App() {
  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 via-blue-50 to-indigo-100">
      <Router>
        <Routes>
          <Route path="/" element={<UploadPage />} />
          <Route path="/dashboard" element={<Dashboard />} />
          <Route path="/research" element={<ResearchInsights />} />
          <Route path="/cam-preview" element={<CAMPreview />} />
        </Routes>
      </Router>
    </div>
  );
}

export default App;
